run-native-hipblaslt-dyadic-r1.ps1.text:
param([ValidateSet('build','test')][string]$Action='build')
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
$repo='D:\projects\AIMA-public-hipblaslt-dyadic-20260914';$seed='D:\projects\AIMA-public-matrix-scope-20260914';$sha='95a33b3378c749f493d12eea331087883fe2595a';$bundle='D:\projects\hipblaslt-dyadic-95a33b3.bundle'
if((Get-FileHash $bundle -Algorithm SHA256).Hash.ToLowerInvariant() -ne 'c2bbe3941472ed586963bbd96353472fad0783b096fabc01944f7478d0f4f5f5'){throw 'Bundle changed'}
if(-not (Test-Path $repo)){& git -C $seed fetch $bundle HEAD;if($LASTEXITCODE -ne 0){throw 'Fetch failed'};& git -C $seed worktree add --detach $repo $sha;if($LASTEXITCODE -ne 0){throw 'Worktree creation failed'}}
if((& git -C $repo rev-parse HEAD).Trim() -ne $sha -or @(& git -C $repo status --porcelain).Count -ne 0){throw 'Source mismatch'}
$build=Join-Path $repo 'build\hipblaslt-dyadic';$null=New-Item -ItemType Directory -Path $build -Force
$source=Join-Path $repo 'tests\native\hipblaslt_dyadic_repro.cpp';$exe=Join-Path $build 'hipblaslt-dyadic.exe';$provenance=Join-Path $build 'build-provenance.json'
$out=Join-Path $repo ('build\hipblaslt-dyadic-'+$Action+'-r1');$specPath=Join-Path $build ($Action+'-spec-r1.json')
if((Test-Path $specPath) -or (Test-Path $out)){throw 'Evidence exists'}
$sourceInputs=@(@{file=$source;sha256=(Get-FileHash $source -Algorithm SHA256).Hash.ToLowerInvariant()})
$spec=[ordered]@{executable='';arguments=@();working_directory=$repo;repo_commit=$sha;command_file=$PSCommandPath;command_file_sha256=(Get-FileHash $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();source_inputs=$sourceInputs;model='none; exact generated dyadic BF16 matrices at complete q8192 shapes';model_loaded=$false;engine_provider_included=$false;inference_acceptance=$false;performance_acceptance=$false;purpose='Isolate observed FP32 producer differences using only public HIP and hipBLASLt APIs. Keep host alpha/beta alive through completion; compare every output against independent int64 numerator /128 and BF16 endpoints; check source and output guards; capture actual loaded library and official benchmark/extended-profile log.'}
$env:PATH='C:\Program Files\AMD\ROCm\7.1\bin;'+$env:PATH
if($Action -eq 'build'){
 $import='C:\Program Files\AMD\ROCm\7.1\lib\libhipblaslt.dll.a';Copy-Item $import (Join-Path $build 'hipblaslt.lib')
 $spec.import_library=@{file=$import;sha256=(Get-FileHash $import -Algorithm SHA256).Hash.ToLowerInvariant()}
 $spec.executable='C:\Program Files\AMD\ROCm\7.1\bin\hipcc.exe';$spec.arguments=@('-std=c++17','-O3','--offload-arch=gfx1151','-L',$build,$source,'-o',$exe,'-lhipblaslt');$timeout=120
}else{
 $meta=[IO.File]::ReadAllText($provenance)|ConvertFrom-Json
 if($meta.repo_commit -ne $sha -or (Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant() -ne $meta.executable.sha256){throw 'Executable provenance mismatch'}
 $spec.build_provenance_sha256=(Get-FileHash $provenance -Algorithm SHA256).Hash.ToLowerInvariant();$spec.executable=$exe;$timeout=120
 $log=Join-Path $build 'hipblaslt-log-r1.txt';if(Test-Path $log){throw 'Library log exists'}
 $env:HIPBLASLT_LOG_MASK='160';$env:HIPBLASLT_LOG_FILE=$log;$spec.library_log=@{mask=160;file=$log}
}
[IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
& (Join-Path $repo 'scripts\baiying_guarded_inference.ps1') -SpecPath $specPath -OutDir $out -TimeoutSeconds $timeout|Out-Null
$r=[IO.File]::ReadAllText((Join-Path $out 'run-record.json'))|ConvertFrom-Json
$r|Select-Object reason,exit_code,wall_ms,host_checks|ConvertTo-Json -Depth 5
if($Action -eq 'test'){
 $reports=@([IO.File]::ReadAllLines((Join-Path $out 'product.stdout.jsonl'))|Where-Object {$_.StartsWith('{')}|ForEach-Object {$_|ConvertFrom-Json})
 $identities=@($reports|Where-Object {$_.type -eq 'loaded_hipblaslt_module'})
 $identity=[ordered]@{host=[Environment]::MachineName;repo_commit=$sha;loaded_module_count=$identities.Count;modules=@();log_present=(Test-Path $log);inference_acceptance=$false;performance_acceptance=$false}
 foreach($id in $identities){$item=Get-Item ([string]$id.path);$identity.modules+=@{file=$item.FullName;bytes=$item.Length;sha256=(Get-FileHash $item.FullName -Algorithm SHA256).Hash.ToLowerInvariant();file_version=[string]$item.VersionInfo.FileVersion;product_version=[string]$item.VersionInfo.ProductVersion}}
 if(Test-Path $log){$identity.log_sha256=(Get-FileHash $log -Algorithm SHA256).Hash.ToLowerInvariant();$identity.log_bytes=(Get-Item $log).Length;Copy-Item $log (Join-Path $out 'hipblaslt-log.txt')}
 [IO.File]::WriteAllText((Join-Path $out 'loaded-library.json'),($identity|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
}
if($r.reason -ne 'completed' -or $r.exit_code -ne 0 -or -not $r.host_checks_pass){throw 'Native standalone diagnostic failed'}
if($Action -eq 'build'){
 $meta=[ordered]@{host=[Environment]::MachineName;repo_commit=$sha;source_inputs=$sourceInputs;command_file=$PSCommandPath;command_file_sha256=$spec.command_file_sha256;compiler=$spec.executable;arguments=$spec.arguments;import_library=$spec.import_library;run_record_sha256=(Get-FileHash (Join-Path $out 'run-record.json') -Algorithm SHA256).Hash.ToLowerInvariant();executable=@{file=$exe;bytes=(Get-Item $exe).Length;sha256=(Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant()}}
 [IO.File]::WriteAllText($provenance,($meta|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
}else{
 $cases=@($reports|Where-Object {$_.type -eq 'standalone_dyadic_case'})
 if($identities.Count -ne 1 -or $cases.Count -ne 4 -or -not $identity.log_present){throw 'Incomplete standalone evidence'}
 foreach($case in $cases){if($case.bf16_mismatches -ne 0 -or -not $case.redzones_pass -or -not $case.immutable_inputs -or -not $case.alpha_live_until_completion){throw 'Standalone endpoint or guard failure'}}
}

